# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MED (UZATMA) HARFLERİ: ELİF (ا) • VAV (و) • YA (ي)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">1. Med Harfi: Elif (ا)</text>\n  <text x="125" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Kural: Üstün (ـَ) + Hareketsiz ا</text>\n  <text x="125" y="128" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">قَالَ (Kâle) • كَانَ (Kâne)</text>\n  <text x="125" y="156" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">كِتَابٌ (Kitâbün) • نَارٌ (Nârun)</text>\n  <text x="125" y="186" text-anchor="middle" font-size="11" fill="#334155">İnce harfleri «â», kalın harfleri</text>\n  <text x="125" y="204" text-anchor="middle" font-size="11" fill="#334155">tok bir «a» sesiyle 1 elif uzatır.</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">2. Med Harfi: Vav (و)</text>\n  <text x="350" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">Kural: Ötre (ـُ) + Hareketsiz و</text>\n  <text x="350" y="128" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">يَقُولُ (Yekûlü) • نُورٌ (Nûrun)</text>\n  <text x="350" y="156" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">سُورَةٌ (Sûratün) • تُوبُوا (Tûbû)</text>\n  <text x="350" y="186" text-anchor="middle" font-size="11" fill="#334155">Ötreli harfi «û / u» sesiyle</text>\n  <text x="350" y="204" text-anchor="middle" font-size="11" fill="#334155">1 elif miktarı uzatarak okutur.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="14" font-weight="bold" fill="#be185d">3. Med Harfi: Ya (ي)</text>\n  <text x="575" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#831843">Kural: Esre (ـِ) + Hareketsiz ي</text>\n  <text x="575" y="128" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">قِيلَ (Kîle) • دِينٌ (Dînün)</text>\n  <text x="575" y="156" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">كَرِيمٌ (Kerîmün) • فِيهَا (Fîhâ)</text>\n  <text x="575" y="186" text-anchor="middle" font-size="11" fill="#334155">Esreli harfi «î / ı» sesiyle</text>\n  <text x="575" y="204" text-anchor="middle" font-size="11" fill="#334155">1 elif miktarı uzatarak okutur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ASLİ MED (MEDD-İ TABİİ) ŞARTLARI VE ÇEKER İŞARETİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Harfin Med Harfi Olma Şartı</text>\n  <text x="182" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">• ا ، و ، ي harflerinde HAREKE veya</text>\n  <text x="182" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">ŞEDDE BULUNMAMALIDIR!</text>\n  <text x="182" y="148" text-anchor="middle" font-size="12" fill="#92400e">✔ قَالَ (Elif harekesiz ➔ Med harfidir)</text>\n  <text x="182" y="172" text-anchor="middle" font-size="12" fill="#92400e">✘ وَ لَدٌ - يَوْمٌ (Vav ve Ya harekeli/cezimli</text>\n  <text x="182" y="192" text-anchor="middle" font-size="12" fill="#92400e">olduğu için burada med harfi değildir)</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" fill="#475569">Ölçü: 1 Elif miktarı (bir parmak kaldırıp indirme süresi)</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Asar (Çeker) İşareti ve Üçlü Örnek</text>\n  <text x="517" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Çeker (ـٰ): Yazıda elif olmadığı hâlde</text>\n  <text x="517" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">harfi 1 elif uzatan dikey işarettir:</text>\n  <text x="517" y="144" text-anchor="middle" font-size="13" font-weight="bold" fill="#581c87">رَحْمٰنُ (Rahmânu) • هٰذَا (Hâzâ) • إِلٰهٌ (İlâhün)</text>\n  <text x="517" y="176" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Üç Med Harfi Tek Kelimede:</text>\n  <text x="517" y="202" text-anchor="middle" font-size="15" font-weight="bold" fill="#3b0764">نُوحِيهَا (Nû - hî - hâ)</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" fill="#475569">نُو (Vav ile) + حِي (Ya ile) + هَا (Elif ile)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUR\'AN OKUMADA MED, CEZİM VE ŞEDDE UYGULAMALARI</text>\n  <rect x="25" y="48" width="650" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Fâtiha Suresi ve Tahiyyat Duasından Uzatmalı Okuma Örnekleri</text>\n  <text x="350" y="106" text-anchor="middle" font-size="14" font-weight="bold" fill="#14532d">• اَلْعَالَمِينَ (El-âlemîne): عَا (Elif ile med) + مِي (Ya ile med)</text>\n  <text x="350" y="136" text-anchor="middle" font-size="14" font-weight="bold" fill="#14532d">• مَالِكِ يَوْمِ الدِّينِ (Mâliki yevmid-dîni): مَا (Elif/Çeker) + دِي (Ya ile med)</text>\n  <text x="350" y="166" text-anchor="middle" font-size="14" font-weight="bold" fill="#14532d">• نَسْتَعِينُ (Neste\'înü) ve الْمُسْتَقِيمَ (El-müstekîme): Ya (ي) ile med</text>\n  <text x="350" y="196" text-anchor="middle" font-size="14" font-weight="bold" fill="#14532d">• اَلتَّحِيَّاتُ لِلّٰهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ: Şedde + Elif/Çeker meddi birlikte</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" fill="#166534">Uzatma harfi olmayan heceler uzatılmaz; med harfi olan heceler ise tam 1 elif çekilir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
